"""``workpeg doctor`` — diagnose the SDK install, project, and CDN delivery.

Fifteen checks over four categories (environment, tooling, project, network),
each traceable to a real incident this repo has hit — the ``pip install .``
that silently froze an editable checkout, the wheel that shipped without an
icon source, the dev server that served a months-stale ``dist/`` chrome, the
CDN publish that reached nobody. Every WARN/FAIL carries the exact command
that fixes it (the runner enforces this), in the spirit of ``flutter doctor``
without ``brew doctor``'s noise: a healthy machine prints ticks and exits 0,
even offline, even outside a project.

Design rules the tests pin:

- **Everything a check observes flows through** :class:`Context` — env,
  ``which``, subprocess, network, SDK asset paths, install metadata. Tests
  build a real Context over ``tmp_path`` fakes; no monkeypatching, no sockets.
- **The network category never FAILs** (PASS/WARN/SKIP only): CDN-first
  chrome degrades to the bundled copy by design, only the Workpeg team can
  fix a broken publish, and the deep gate is ``scripts/canary.py`` in CI. So
  network state can never flip the exit code — not on planes, captive
  portals, or CDN incidents — and ``--strict`` does not promote network
  WARNs.
- **Freshness is judged by content, never mtime** where it matters: the
  stale-dist incident survived mtime inspection (``git checkout`` and
  ``cp -p`` lie), so ``dist-chrome-fresh`` hashes bytes.
- Exit codes: 0 = no FAIL (WARNs allowed unless ``--strict``); 1 = a FAIL,
  or a non-network WARN under ``--strict``; 2 = doctor itself crashed (the
  cli handler owns that — a crash must not masquerade as a verdict).
"""
from __future__ import annotations

import enum
import hashlib
import json
import os
import platform
import queue
import re
import shutil
import subprocess
import sys
import threading
import time
import traceback
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Mapping

#: Mirrors pyproject's ``requires-python = ">=3.10"``, spelled out rather
#: than parsed at runtime (tomllib is 3.11+, and doctor must run on the very
#: interpreter it is diagnosing). A test regex-pins the two together.
PY_FLOOR = (3, 10)

#: Composed, not one literal: the runtime builds these the same way
#: (``Workpeg._CDN + "/scaffold/scaffold.js"``), so a full-URL grep of the
#: runtime source finds nothing. A test pins the base and each fragment as
#: quoted literals in workpeg-runtime.js.
CDN_BASE = "https://cdn.workpeg.com"
CDN_SCAFFOLD = CDN_BASE + "/scaffold/scaffold.js"
CDN_AI = CDN_BASE + "/ai/ai.js"

ISSUES_URL = "https://gitlab.com/workpeg/workpeg-sdk/-/issues"

#: How many bytes a network probe may read. Enough to sniff an HTML error
#: page; never enough to pull the ~26 MB icon sheet (a test records every
#: fetch's max_bytes to prove it).
PROBE_BYTES = 1024


class Status(str, enum.Enum):
    PASS = "pass"
    INFO = "info"
    WARN = "warn"
    FAIL = "fail"
    SKIP = "skip"


@dataclass(frozen=True)
class Result:
    status: Status
    summary: str
    remedy: str = ""      # required on WARN/FAIL — the runner asserts it
    detail: str = ""      # shown under --verbose only


@dataclass(frozen=True)
class Check:
    id: str               # stable kebab-case — the --json contract
    category: str         # environment | tooling | project | network
    run: Callable[["Context"], Result]


@dataclass(frozen=True)
class SdkPaths:
    """The installed SDK's runtime assets. Defaults resolve from
    ``workpeg.ui.build``'s own constants (lazily — importing the UI compiler
    costs ~100ms, and doctor must not tax ``workpeg --help``); injectable so
    tests point at tmp_path with zero monkeypatching."""
    runtime_js: Path
    pegment_css: Path
    scaffold_js: Path
    ai_js: Path
    icons_css: Path
    icons_css_gz: Path


@dataclass(frozen=True)
class FetchResult:
    status: int
    content_type: str
    cache_control: str
    final_url: str
    body_prefix: bytes


class Unreachable(Exception):
    """The probe could not complete: DNS, TLS, timeout, or the collector's
    overall deadline. Deliberately one exception — doctor treats every
    flavour of "no answer" identically (SKIP, never a failure)."""


def _default_fetch(url: str, max_bytes: int = PROBE_BYTES,
                   timeout: float = 3.0) -> FetchResult:
    req = urllib.request.Request(
        url,
        # A Range read: the icons sheet is ~26 MB and doctor only sniffs.
        headers={"Range": f"bytes=0-{max_bytes - 1}",
                 "User-Agent": "workpeg-doctor"},
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            # r.headers, never dict(r.headers): header names are
            # case-insensitive and dict() would make lookups case-sensitive
            # (the CDN sends "Content-Type", SimpleHTTP sends
            # "Content-type" — scripts/canary.py hit exactly this).
            return FetchResult(
                status=r.status,
                content_type=r.headers.get("Content-Type", "") or "",
                cache_control=r.headers.get("Cache-Control", "") or "",
                final_url=r.geturl(),
                body_prefix=r.read(max_bytes),
            )
    except urllib.error.HTTPError as e:
        return _fetch_from_http_error(e, url, max_bytes)
    except Exception as e:          # URLError, timeout, TLS — all "no answer"
        raise Unreachable(str(e))


def _fetch_from_http_error(e, url: str, max_bytes: int) -> FetchResult:
    """An HTTP error page is an ANSWER, not an outage — surface it. The body
    read is bounded like the success path: e.read() with no argument drains
    the whole error body (a 5 MB error page to keep 1 KB)."""
    try:
        body = e.read(max_bytes) if e.fp else b""
    except Exception:
        body = b""
    return FetchResult(
        status=e.code,
        content_type=e.headers.get("Content-Type", "") or "",
        cache_control=e.headers.get("Cache-Control", "") or "",
        final_url=url,
        body_prefix=body,
    )


def _default_run_tool(cmd: list[str]) -> str | None:
    """First line of a tool's output, or None on ANY failure — a missing
    binary, a hang past 2s, a non-zero exit. Doctor reports absence; it never
    crashes on it."""
    try:
        out = subprocess.run(cmd, capture_output=True, text=True, timeout=2)
        if out.returncode != 0:
            return None
        return (out.stdout or out.stderr).strip().splitlines()[0]
    except Exception:
        return None


def _load_sdk_paths() -> SdkPaths:
    from workpeg.ui import build as b
    runtime = b._RUNTIME_JS
    return SdkPaths(
        runtime_js=runtime,
        pegment_css=b._PEGMENT_CSS,
        scaffold_js=b._SCAFFOLD_JS,
        ai_js=b._AI_JS,
        icons_css=b._ICONS_CSS,
        icons_css_gz=b._ICONS_CSS_GZ,
    )


@dataclass
class Context:
    """Everything the checks may observe, injected once. ``build_context``
    fills it from the real machine; tests fill it from tmp_path fakes."""
    target: Path
    kinds: frozenset[str]                   # subset of {"ui","function","dist"}
    dist_dir: Path | None
    checkout: Path | None                   # nearest SDK checkout over target
    workpeg_file: Path
    workpeg_version: str
    workpeg_editable: bool | None           # direct_url.json dir_info.editable
    workpeg_origin: str | None              # direct_url.json url
    py_version: tuple[int, int, int]
    platform_str: str
    env: Mapping[str, str]                  # never os.environ inside a check
    which: Callable[[str], str | None]
    run_tool: Callable[[list[str]], str | None]
    fetch: Callable[..., FetchResult]
    sdk_paths_loader: Callable[[], SdkPaths]
    offline: bool = False
    timeout: float = 3.0
    _sdk_paths: SdkPaths | None = field(default=None, repr=False)
    _probes: dict | None = field(default=None, repr=False)

    def sdk_paths(self) -> SdkPaths:
        if self._sdk_paths is None:
            self._sdk_paths = self.sdk_paths_loader()
        return self._sdk_paths


# ── context construction ────────────────────────────────────────────────


def _find_checkout(start: Path) -> Path | None:
    """The nearest ancestor of *start* (inclusive) that IS the SDK checkout:
    a pyproject.toml naming workpeg plus a src/workpeg/ tree. Regex over
    text, not tomllib — the floor is 3.10 and tomllib is 3.11+."""
    for cand in (start, *start.parents):
        py = cand / "pyproject.toml"
        if not py.is_file():
            continue
        try:
            txt = py.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            # An unreadable or non-UTF-8 pyproject.toml cannot be the SDK
            # checkout's (this repo's is ASCII) — skip, never crash the run.
            continue
        if (re.search(r'^name = "workpeg"$', txt, re.M)
                and (cand / "src" / "workpeg").is_dir()):
            return cand
    return None


def _install_metadata() -> tuple[str, bool | None, str | None]:
    """(version, editable, origin) from importlib.metadata — absence of any
    piece degrades to unknowns rather than crashing the doctor."""
    version, editable, origin = "unknown", None, None
    try:
        from importlib.metadata import distribution
        dist = distribution("workpeg")
        version = dist.version
        raw = dist.read_text("direct_url.json")
        if raw:
            data = json.loads(raw)
            origin = data.get("url")
            editable = data.get("dir_info", {}).get("editable")
    except Exception:
        pass
    return version, editable, origin


def detect_target(target: Path) -> tuple[frozenset[str], Path | None]:
    """What is at *target*? A UI project (main.py), a Function project
    (workpeg.json), a prebuilt dist (index.html + workpeg-runtime.js — the
    stale-chrome incident's artifact, doctorable directly), or nothing."""
    kinds = set()
    if (target / "main.py").is_file():
        kinds.add("ui")
    if (target / "workpeg.json").is_file():
        kinds.add("function")
    dist_dir: Path | None = None
    if not kinds and (target / "index.html").is_file() \
            and (target / "workpeg-runtime.js").is_file():
        kinds.add("dist")
        dist_dir = target
    elif "ui" in kinds:
        d = target / "dist"
        dist_dir = d if d.is_dir() else None
    return frozenset(kinds), dist_dir


def build_context(target: Path, *, offline: bool = False,
                  timeout: float = 3.0) -> Context:
    import workpeg
    target = target.resolve()
    kinds, dist_dir = detect_target(target)
    version, editable, origin = _install_metadata()
    return Context(
        target=target,
        kinds=kinds,
        dist_dir=dist_dir,
        checkout=_find_checkout(target),
        workpeg_file=Path(workpeg.__file__).resolve(),
        workpeg_version=version,
        workpeg_editable=editable,
        workpeg_origin=origin,
        py_version=sys.version_info[:3],
        platform_str=f"{platform.system()} {platform.machine()}",
        env=dict(os.environ),
        which=shutil.which,
        run_tool=_default_run_tool,
        fetch=_default_fetch,
        sdk_paths_loader=_load_sdk_paths,
        offline=offline,
        timeout=timeout,
    )


# ── environment checks ──────────────────────────────────────────────────


def _check_python(ctx: Context) -> Result:
    ver = ".".join(map(str, ctx.py_version))
    floor = ".".join(map(str, PY_FLOOR))
    if ctx.py_version[:2] >= PY_FLOOR:
        return Result(Status.PASS, f"Python {ver} (>= {floor} required)")
    return Result(
        Status.FAIL,
        f"Python {ver} is below the supported floor ({floor})",
        remedy=("recreate the venv on a supported interpreter: "
                "python3.12 -m venv .venv && "
                ".venv/bin/pip install workpeg"),
    )


def _is_site_packages(p: Path) -> bool:
    return "site-packages" in p.parts or "dist-packages" in p.parts


def _check_install_mode(ctx: Context) -> Result:
    pkg_dir = ctx.workpeg_file.parent
    detail = (f"path={pkg_dir} version={ctx.workpeg_version} "
              f"editable={ctx.workpeg_editable} origin={ctx.workpeg_origin}")
    if ctx.workpeg_editable is True:
        return Result(Status.PASS, f"editable install — {pkg_dir}",
                      detail=detail)
    if not _is_site_packages(ctx.workpeg_file) \
            and "src" in ctx.workpeg_file.parts:
        # No direct_url.json but importing straight from a src tree —
        # editable in effect (older pip / PYTHONPATH setups).
        return Result(Status.PASS, f"editable install — {pkg_dir}",
                      detail=detail)
    if _is_site_packages(ctx.workpeg_file):
        # version "0" is the checkout's pinned dev version (pyproject) — in
        # site-packages it can only mean a `pip install .` froze the dev
        # tree. This exact accident (via `pip install '.[docs]'`) cost a
        # debugging session: builds silently read the stale snapshot.
        if ctx.workpeg_version == "0":
            origin_path = ""
            if ctx.workpeg_origin and ctx.workpeg_origin.startswith("file://"):
                # pip writes url via pathname2url: percent-encoded, and
                # file:///C:/... on Windows — a naive slice would tell the
                # user to `pip install -e /C:/...` or a %20-mangled path.
                from urllib.parse import urlsplit
                from urllib.request import url2pathname
                origin_path = url2pathname(urlsplit(ctx.workpeg_origin).path)
            if origin_path or ctx.checkout:
                where = origin_path or str(ctx.checkout)
                return Result(
                    Status.FAIL,
                    "frozen copy of the SDK checkout "
                    "(version 0 in site-packages)",
                    remedy=(f"pip install -e {where}   "
                            f"(extras too: pip install -e '.[docs]' — "
                            f"a plain '.[docs]' also freezes)"),
                    detail=detail,
                )
            return Result(
                Status.WARN,
                "frozen dev snapshot of the SDK (version 0 in site-packages)",
                remedy=("deliberate git+https pin? fine. Otherwise: "
                        "pip install --force-reinstall workpeg"),
                detail=detail,
            )
        if ctx.checkout:
            return Result(
                Status.WARN,
                f"a released wheel ({ctx.workpeg_version}) imports here, "
                f"but you're inside the SDK checkout — edits to src/ "
                f"won't run",
                remedy="developing the SDK? pip install -e .",
                detail=detail,
            )
        return Result(Status.PASS,
                      f"workpeg {ctx.workpeg_version} (wheel)",
                      detail=detail)
    return Result(Status.PASS,
                  f"workpeg {ctx.workpeg_version} — {pkg_dir}", detail=detail)


def _check_icons_source(ctx: Context) -> Result:
    try:
        paths = ctx.sdk_paths()
    except Exception as e:
        return Result(Status.FAIL,
                      f"cannot import workpeg.ui.build: {e!r}",
                      remedy="pip install --force-reinstall workpeg")
    if paths.icons_css.is_file():
        return Result(Status.PASS, "icon source: icons.css (raw checkout copy)")
    if paths.icons_css_gz.is_file():
        return Result(Status.PASS, "icon source: icons.css.gz (packaged)")
    return Result(
        Status.WARN,
        "no icon source — neither icons.css nor icons.css.gz in the "
        "installed package. Icon subsetting is disabled: icon-using builds "
        "link the ~26 MB CDN sheet, and dev builds show blank icons offline",
        remedy=("pip install --force-reinstall workpeg   (checkout: "
                "git checkout src/workpeg/ui/runtime/ && pip install -e .)"),
    )


def _check_chrome_bundles(ctx: Context) -> Result:
    try:
        paths = ctx.sdk_paths()
    except Exception as e:
        return Result(Status.FAIL,
                      f"cannot import workpeg.ui.build: {e!r}",
                      remedy="pip install --force-reinstall workpeg")
    # Severity mirrors build_ui byte-for-byte: runtime + pegment are
    # unconditional read_text (a build CRASHES without them); scaffold + ai
    # sit behind silent is_file() guards (a build quietly ships a chrome-less
    # app), so their absence warns rather than fails.
    hard = [p.name for p in (paths.runtime_js, paths.pegment_css)
            if not p.is_file()]
    soft = [p.name for p in (paths.scaffold_js, paths.ai_js)
            if not p.is_file()]
    remedy = ("pip install --force-reinstall workpeg   "
              "(checkout: restore src/workpeg/ui/runtime/)")
    if hard:
        return Result(Status.FAIL,
                      f"missing {', '.join(hard)} — every build crashes",
                      remedy=remedy)
    if soft:
        return Result(
            Status.WARN,
            f"missing {', '.join(soft)} — builds succeed but ship no "
            f"bundled fallback: chrome=bundled apps get no chrome, and "
            f"chrome=auto apps break the moment the CDN doesn't answer",
            remedy=remedy,
        )
    return Result(Status.PASS, "chrome bundles: workpeg-runtime.js, "
                               "pegment.css, scaffold.js, ai.js")


def _check_env_overrides(ctx: Context) -> Result:
    findings: list[tuple[Status, str, str]] = []
    chrome = ctx.env.get("WORKPEG_CHROME")
    if chrome is not None:
        try:
            from workpeg.ui.build import CHROME_SOURCES
        except Exception:
            CHROME_SOURCES = ("auto", "bundled")
        if chrome == "auto":
            # Equal to the built-in default: a pure no-op. Surfacing it as a
            # WARN would fail --strict CI over nothing.
            findings.append((
                Status.INFO,
                "WORKPEG_CHROME=auto is set — redundant (auto is already "
                "the default); unset it to reduce surprise",
                "",
            ))
        elif chrome in CHROME_SOURCES:
            findings.append((
                Status.WARN,
                f"WORKPEG_CHROME={chrome} is set — every 'workpeg ui build' "
                f"on this machine defaults to --chrome {chrome}",
                "unset WORKPEG_CHROME   (keep it only if this machine "
                "builds for local development or tests, never a release)",
            ))
        else:
            findings.append((
                Status.FAIL,
                f"WORKPEG_CHROME={chrome} is invalid — every 'workpeg ui "
                f"build' on this machine refuses to run, since the env "
                f"supplies the --chrome default",
                "set WORKPEG_CHROME to auto or bundled, or unset it",
            ))
    if ctx.env.get("WORKPEG_API_BASE"):
        findings.append((
            Status.INFO,
            f"WORKPEG_API_BASE is set — submits target "
            f"{ctx.env['WORKPEG_API_BASE']} instead of the default registry",
            "",
        ))
    if ctx.env.get("WORKPEG_BIND_HOST"):
        findings.append((
            Status.INFO,
            f"WORKPEG_BIND_HOST={ctx.env['WORKPEG_BIND_HOST']} is set — "
            f"dev servers bind there instead of 127.0.0.1",
            "",
        ))
    if not findings:
        return Result(Status.PASS, "no Workpeg env overrides set")
    order = [Status.FAIL, Status.WARN, Status.INFO]
    worst = min((f[0] for f in findings), key=order.index)
    return Result(
        worst,
        "; ".join(f[1] for f in findings),
        remedy="; ".join(f[2] for f in findings if f[2]),
    )


# ── tooling checks ──────────────────────────────────────────────────────


def _check_node(ctx: Context) -> Result:
    if ctx.which("node"):
        ver = ctx.run_tool(["node", "--version"]) or "version unknown"
        return Result(Status.PASS, f"node {ver}")
    if ctx.checkout:
        return Result(
            Status.WARN,
            "node not found — the SDK checkout's JS harnesses "
            "(tests/scaffold, tests/ai, tests/runtime), tests/e2e and "
            "scripts/canary.py all need it",
            remedy="brew install node   (or nodejs.org)",
        )
    return Result(Status.INFO,
                  "node not found — only the SDK's own test harnesses and "
                  "scripts/canary.py need it")


def _check_docker(ctx: Context) -> Result:
    # Client version only — deliberately never `docker info`, which blocks on
    # a down daemon and would blow the 2s tool budget.
    if ctx.which("docker"):
        ver = ctx.run_tool(["docker", "--version"]) or "version unknown"
        return Result(Status.PASS, ver)
    return Result(Status.INFO,
                  "docker not found — only 'workpeg function build' and "
                  "'run --with docker' need it")


# ── project checks ──────────────────────────────────────────────────────


def _check_project_kind(ctx: Context) -> Result:
    if not ctx.kinds:
        return Result(
            Status.INFO,
            "no Peg project here (no main.py or workpeg.json) — project "
            "checks skipped. Run from a project directory, or: "
            "workpeg doctor path/to/peg",
        )
    names = {"ui": "UI project", "function": "Function project",
             "dist": "prebuilt dist"}
    kinds = " + ".join(names[k] for k in sorted(ctx.kinds))
    return Result(Status.INFO, kinds)


def _check_workpeg_json(ctx: Context) -> Result:
    path = ctx.target / "workpeg.json"
    if not ctx.kinds or not path.is_file():
        return Result(Status.SKIP, "no workpeg.json")
    try:
        json.loads(path.read_text(encoding="utf-8"))
    except UnicodeDecodeError as e:
        return Result(
            Status.FAIL,
            f"workpeg.json is not UTF-8 ({e.reason} at byte {e.start}) — "
            f"every 'workpeg function' command reads this file",
            remedy=("re-save workpeg.json as UTF-8 without a BOM (an editor "
                    "likely wrote it as UTF-16)"),
        )
    except json.JSONDecodeError as e:
        # config.load_config does this same parse UNCAUGHT — every
        # `workpeg function` command dies on this file. A drift test pins
        # load_config raising on the same fixture.
        return Result(
            Status.FAIL,
            f"workpeg.json is not valid JSON: {e.msg} "
            f"(line {e.lineno}, column {e.colno}) — every "
            f"'workpeg function' command reads this file",
            remedy=(f"fix the syntax at workpeg.json:{e.lineno}:{e.colno}, "
                    f"or delete the file to fall back to defaults"),
        )
    except OSError as e:
        return Result(Status.FAIL, f"workpeg.json unreadable: {e}",
                      remedy="check the file's permissions")
    return Result(Status.PASS, "workpeg.json is valid")


#: sha1 memo for SDK-side hash arms, keyed on (path, mtime_ns, size) so a
#: doctor run computes each at most once.
_sdk_hash_memo: dict[tuple, frozenset[str]] = {}


def _sdk_hashes(path: Path, banner: str | None) -> frozenset[str]:
    st = path.stat()
    key = (str(path), st.st_mtime_ns, st.st_size, banner)
    if key not in _sdk_hash_memo:
        src = path.read_text(encoding="utf-8")
        arms = {hashlib.sha1(src.encode("utf-8")).hexdigest()}
        try:
            from workpeg.ui.minify import minify_js
            minified = minify_js(src, banner=banner) if banner \
                else minify_js(src)
            arms.add(hashlib.sha1(minified.encode("utf-8")).hexdigest())
        except Exception:
            # minify.py silently returns source unminified when rjsmin is
            # absent — the raw arm above already covers that build.
            pass
        _sdk_hash_memo.clear()      # one doctor run's worth is plenty
        _sdk_hash_memo[key] = frozenset(arms)
    return _sdk_hash_memo[key]


def _check_dist_chrome_fresh(ctx: Context) -> Result:
    if not ctx.kinds or not ctx.dist_dir:
        return Result(Status.SKIP, "no dist/ to compare")
    try:
        paths = ctx.sdk_paths()
    except Exception as e:
        return Result(Status.FAIL,
                      f"cannot import workpeg.ui.build: {e!r}",
                      remedy="pip install --force-reinstall workpeg")
    from workpeg.ui.minify import RUNTIME_BANNER
    # CONTENT, never mtime: the stale-chrome incident survived mtime
    # inspection (git checkout / cp -p preserve timestamps). A dist file is
    # fresh iff its bytes hash to the SDK source's raw OR minified form —
    # raw covers minify=False builds and the rjsmin-missing fallback;
    # the runtime's minified arm carries build_ui's banner.
    pairs = [
        ("scaffold.js", paths.scaffold_js, None),
        ("ai.js", paths.ai_js, None),
        ("workpeg-runtime.js", paths.runtime_js, RUNTIME_BANNER),
    ]
    stale, compared = [], 0
    for name, sdk_path, banner in pairs:
        dist_file = ctx.dist_dir / name
        if not dist_file.is_file() or not sdk_path.is_file():
            continue
        compared += 1
        # Windows write_text translates \n to \r\n in the dist while the
        # SDK arms hash the source text — normalize, or every Windows-built
        # dist reads as stale. Still content, never mtime.
        raw = dist_file.read_bytes().replace(b"\r\n", b"\n")
        got = hashlib.sha1(raw).hexdigest()
        if got not in _sdk_hashes(sdk_path, banner):
            stale.append(name)
    if not compared:
        return Result(Status.SKIP, "dist/ has no chrome files to compare")
    if stale:
        # WARN, not FAIL: byte-pinned deploys and dists built by a different
        # (but deliberate) SDK are legitimate; --strict promotes this in CI.
        return Result(
            Status.WARN,
            f"dist/{', dist/'.join(stale)} was built by a different SDK "
            f"than the one installed — the served chrome is stale, and "
            f"mtimes/reloads won't show it",
            remedy=(f"workpeg ui build {ctx.target}   (then restart "
                    f"'workpeg ui serve' if it's running)"),
        )
    return Result(Status.PASS, "dist/ chrome matches the installed SDK")


def _check_chrome_policy(ctx: Context) -> Result:
    if not ctx.kinds or not ctx.dist_dir \
            or not (ctx.dist_dir / "index.html").is_file():
        return Result(Status.SKIP, "no dist/index.html")
    html = (ctx.dist_dir / "index.html").read_text(encoding="utf-8")
    bundled = 'data-chrome="bundled"' in html
    # The mount signal: build.py emits this preconnect iff the app mounts a
    # Scaffold AND the policy is auto — the only reliable "this app loads
    # chrome" marker a dist carries.
    preconnect = f'<link rel="preconnect" href="{CDN_BASE}">' in html
    has_scaffold = (ctx.dist_dir / "scaffold.js").is_file()
    if bundled:
        if not has_scaffold:
            # No mount signal exists under bundled, so never FAIL — the app
            # may genuinely have no Scaffold.
            return Result(
                Status.WARN,
                'data-chrome="bundled" but no dist/scaffold.js — if this '
                "app mounts a Scaffold, its chrome can never load",
                remedy=(f"workpeg ui build {ctx.target}   (with the current "
                        f"SDK; or --chrome auto to allow the CDN copy)"),
            )
        return Result(
            Status.INFO,
            "chrome policy: bundled — same-origin only (normal for "
            "'workpeg ui serve' dev builds; a deployed copy won't receive "
            "CDN chrome updates)",
        )
    if preconnect and not has_scaffold:
        return Result(
            Status.WARN,
            "this app mounts chrome (CDN preconnect present) but ships no "
            "bundled scaffold.js — it works only while cdn.workpeg.com "
            "answers",
            remedy=f"workpeg ui build {ctx.target}",
        )
    return Result(
        Status.INFO,
        "chrome policy: auto — CDN-first, bundled fallback (out-of-band "
        "chrome updates reach this app)",
    )


#: Directories that never hold app sources — PRUNED from the walk (not
#: filtered after), so a stray venv or node_modules can't make doctor slow.
_SOURCE_EXCLUDE = {"dist", "node_modules", "__pycache__", ".git", "venv",
                   ".venv"}


def _iter_sources(target: Path):
    """Every source file dist-app-fresh compares: *.py anywhere (excluded
    dirs pruned mid-walk — rglob can't prune and would scan node_modules in
    full) plus everything under public/ (copied verbatim into the dist)."""
    for root, dirnames, filenames in os.walk(target):
        dirnames[:] = [d for d in dirnames
                       if d not in _SOURCE_EXCLUDE and not d.startswith(".")]
        rootp = Path(root)
        in_public = "public" in rootp.relative_to(target).parts
        for f in filenames:
            if f.endswith(".py") or in_public:
                yield rootp / f


def _check_dist_app_fresh(ctx: Context) -> Result:
    if "ui" not in ctx.kinds or not ctx.dist_dir \
            or not (ctx.dist_dir / "index.html").is_file():
        return Result(Status.SKIP, "no built dist/ to compare against")
    built = (ctx.dist_dir / "index.html").stat().st_mtime
    newest, newest_path = 0.0, None
    for p in _iter_sources(ctx.target):
        try:
            if not p.is_file():          # dangling symlink, or a dir *.py
                continue
            m = p.stat().st_mtime
        except OSError:
            continue
        if m > newest:
            newest, newest_path = m, p
    if newest_path and newest > built:
        # INFO, never WARN: mtimes lie (git checkout, cp -p), so this must
        # never fail CI even under --strict. It's a nudge, not a verdict.
        rel = newest_path.relative_to(ctx.target)
        return Result(
            Status.INFO,
            f"{rel} changed after dist/ was last built — a served prebuilt "
            f"dist shows old code. Rebuild: workpeg ui build {ctx.target}   "
            f"(or 'workpeg ui serve', which rebuilds and watches)",
        )
    return Result(Status.PASS, "sources unchanged since the last build")


# ── network checks ──────────────────────────────────────────────────────


def _icons_cdn_url() -> str:
    try:
        from workpeg.ui.build import ICONS_CDN
        return ICONS_CDN
    except Exception:
        return CDN_BASE + "/icons/icons.css"


def _probe_all(ctx: Context) -> dict[str, "FetchResult | Exception"]:
    """All three CDN probes, once per doctor run: daemon threads + a queue
    behind ONE overall deadline (timeout + 1s), so a black-holed
    getaddrinfo on a half-up VPN cannot hold the process — a plain
    sequential loop would serialise three full timeouts."""
    if ctx._probes is not None:
        return ctx._probes
    urls = [CDN_SCAFFOLD, CDN_AI, _icons_cdn_url()]
    q: queue.Queue = queue.Queue()

    def probe(u: str) -> None:
        try:
            q.put((u, ctx.fetch(u, max_bytes=PROBE_BYTES,
                                timeout=ctx.timeout)))
        except Exception as e:
            q.put((u, e))

    for u in urls:
        threading.Thread(target=probe, args=(u,), daemon=True).start()
    results: dict[str, FetchResult | Exception] = {}
    deadline = time.monotonic() + ctx.timeout + 1.0
    for _ in urls:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        try:
            u, r = q.get(timeout=remaining)
            results[u] = r
        except queue.Empty:
            break
    for u in urls:
        results.setdefault(u, Unreachable("probe deadline exceeded"))
    ctx._probes = results
    return results


def _looks_html(res: FetchResult) -> bool:
    ct = res.content_type.lower()
    return ("javascript" not in ct and "css" not in ct
            and res.body_prefix.lstrip().startswith(b"<"))


def _intercepted(probes: dict) -> bool:
    """A captive portal or intercepting proxy answers EVERYTHING with the
    same success-ish HTML; a genuinely broken publish doesn't. Two guards
    keep a real CDN incident from being mislabelled "your wifi":

    - an on-host HTTP ERROR (404/5xx from cdn.workpeg.com itself) is CDN
      ground truth, not portal evidence — a wiped bucket serves 404 HTML for
      every asset and must reach the per-asset escalate/canary WARN;
    - one lone HTML response (plus timeouts) is not corroboration — portals
      answer everything, so demand at least two completed probes.
    """
    completed = [r for r in probes.values() if isinstance(r, FetchResult)]
    if any(CDN_BASE.split("//")[1] not in r.final_url for r in completed):
        return True                       # redirected off-host: intercepted
    if len(completed) < 2:
        return False
    return all(_looks_html(r) and r.status < 400 for r in completed)


def _cdn_check(ctx: Context, url: str, label: str, want: str,
               consequence: str, canary_global: str | None) -> Result:
    if ctx.offline:
        return Result(Status.SKIP, "skipped (--offline)")
    probes = _probe_all(ctx)
    res = probes[url]
    canary = (f"python scripts/canary.py {url} --global {canary_global}"
              if canary_global else "escalate to the Workpeg team")
    if isinstance(res, Exception):
        return Result(
            Status.SKIP,
            f"cdn.workpeg.com unreachable — you're offline, or the CDN is "
            f"down. Offline is fine: chrome=auto apps fall back to their "
            f"bundled copy by design. If you ARE online: {canary}",
        )
    if _intercepted(probes):
        return Result(
            Status.WARN,
            "network intercepted — a captive portal or proxy answered for "
            "cdn.workpeg.com; treat this machine as offline",
            remedy="log into the portal / leave the proxy, then re-run",
        )
    ct = res.content_type.lower()
    ok_status = res.status in (200, 206)
    ok_type = want in ct
    # For the JS bundles a missing max-age is its own incident class: apps
    # would either never see an update or never cache one (canary.py's
    # check, born of a real publish bug).
    ok_cache = ("max-age" in res.cache_control) if want == "javascript" \
        else True
    if ok_status and ok_type and ok_cache:
        cache = " · max-age set" if want == "javascript" else ""
        return Result(Status.PASS,
                      f"{label} — {res.status} · {want}{cache}")
    what = f"{res.status}/{res.content_type or 'no content-type'}"
    if ok_status and ok_type and not ok_cache:
        what = f"{res.status} · {want} · no max-age"
    return Result(
        Status.WARN,
        f"cdn.workpeg.com is serving {what} for {label} — {consequence}",
        remedy=f"escalate to the Workpeg team; deep check: {canary}",
    )


def _check_cdn_scaffold(ctx: Context) -> Result:
    return _cdn_check(
        ctx, CDN_SCAFFOLD, "scaffold.js", "javascript",
        "every chrome=auto app is silently falling back to its bundled "
        "copy; out-of-band chrome updates reach no one",
        "WorkpegScaffold",
    )


def _check_cdn_ai(ctx: Context) -> Result:
    return _cdn_check(
        ctx, CDN_AI, "ai.js", "javascript",
        "the /b/<biz>/chats/* surfaces of chrome=auto apps fall back to "
        "their bundled copy",
        "WorkpegAI",
    )


def _check_cdn_icons(ctx: Context) -> Result:
    return _cdn_check(
        ctx, _icons_cdn_url(), "icons.css", "css",
        "builds that link the CDN icon sheet (dynamic icon names, or "
        "installs missing both local icon sources) render blank icons; "
        "static-icon builds ship a subset and are unaffected",
        None,
    )


# ── the registry (output order) ─────────────────────────────────────────

CHECKS: tuple[Check, ...] = (
    Check("python-version", "environment", _check_python),
    Check("install-mode", "environment", _check_install_mode),
    Check("icons-source", "environment", _check_icons_source),
    Check("chrome-bundles", "environment", _check_chrome_bundles),
    Check("env-overrides", "environment", _check_env_overrides),
    Check("node", "tooling", _check_node),
    Check("docker", "tooling", _check_docker),
    Check("project-kind", "project", _check_project_kind),
    Check("workpeg-json", "project", _check_workpeg_json),
    Check("dist-chrome-fresh", "project", _check_dist_chrome_fresh),
    Check("chrome-policy", "project", _check_chrome_policy),
    Check("dist-app-fresh", "project", _check_dist_app_fresh),
    Check("cdn-scaffold", "network", _check_cdn_scaffold),
    Check("cdn-ai", "network", _check_cdn_ai),
    Check("cdn-icons", "network", _check_cdn_icons),
)


# ── runner + report ─────────────────────────────────────────────────────


@dataclass(frozen=True)
class Report:
    results: tuple[tuple[Check, Result], ...]
    elapsed: float

    def counts(self) -> dict[str, int]:
        out = {s.value: 0 for s in Status}
        for _, r in self.results:
            out[r.status.value] += 1
        return out

    def exit_code(self, strict: bool = False) -> int:
        for check, r in self.results:
            if r.status is Status.FAIL:
                return 1
            # Network is advisory by invariant: the CDN degrading must never
            # fail CI (the deep gate is scripts/canary.py in its own job).
            if strict and r.status is Status.WARN \
                    and check.category != "network":
                return 1
        return 0


def run_doctor(ctx: Context,
               checks: tuple[Check, ...] = CHECKS) -> Report:
    started = time.monotonic()
    results = []
    for check in checks:
        try:
            r = check.run(ctx)
        except Exception as e:
            # One broken check must not hide the other fourteen — fence it
            # and keep going. A network check's crash demotes to WARN: the
            # category's never-FAIL invariant (network state must not flip
            # the exit code) has to hold even when the state breaks doctor's
            # own probe code.
            fenced = Status.WARN if check.category == "network" \
                else Status.FAIL
            r = Result(fenced, f"check crashed: {e!r}",
                       remedy=f"report this: {ISSUES_URL}",
                       detail=traceback.format_exc())
        if r.status in (Status.WARN, Status.FAIL) and not r.remedy:
            # "Every failure carries its fix" is a contract, not a hope.
            r = Result(r.status, r.summary,
                       remedy=f"report this (missing remedy): {ISSUES_URL}",
                       detail=r.detail)
        results.append((check, r))
    return Report(tuple(results), time.monotonic() - started)


# ── rendering ───────────────────────────────────────────────────────────

_GLYPHS = {Status.PASS: "✓", Status.INFO: "·", Status.WARN: "!",
           Status.FAIL: "✗", Status.SKIP: "·",
           "arrow": "→", "sep": " · "}
_ASCII = {Status.PASS: "[ok]", Status.INFO: "[i]", Status.WARN: "[!]",
          Status.FAIL: "[x]", Status.SKIP: "[-]",
          "arrow": "->", "sep": " - "}
_COLORS = {Status.PASS: "\x1b[32m", Status.INFO: "\x1b[2m",
           Status.WARN: "\x1b[33m", Status.FAIL: "\x1b[31m",
           Status.SKIP: "\x1b[2m"}
_RESET = "\x1b[0m"
_SECTIONS = (("environment", "Environment"), ("tooling", "Tooling"),
             ("project", "Project"), ("network", "Network"))


def _use_color(stream) -> bool:
    return (getattr(stream, "isatty", lambda: False)()
            and not os.environ.get("NO_COLOR"))


def _glyphs_for(stream) -> dict:
    try:
        "✓".encode(getattr(stream, "encoding", None) or "utf-8")
        return _GLYPHS
    except (UnicodeEncodeError, LookupError):
        return _ASCII


def _header(ctx: Context, sep: str = " · ") -> str:
    editable = " (editable)" if ctx.workpeg_editable else ""
    py = ".".join(map(str, ctx.py_version))
    return sep.join(["workpeg doctor",
                     f"workpeg {ctx.workpeg_version}{editable}",
                     f"Python {py}", ctx.platform_str])


def render_text(report: Report, ctx: Context, *, verbose: bool = False,
                color: bool = False, glyphs: dict | None = None) -> str:
    glyphs = glyphs or _GLYPHS
    lines = [_header(ctx, glyphs["sep"]), ""]
    by_cat: dict[str, list] = {}
    for check, r in report.results:
        by_cat.setdefault(check.category, []).append((check, r))
    for cat, title in _SECTIONS:
        rows = by_cat.get(cat, [])
        shown = [(c, r) for c, r in rows
                 if verbose or r.status is not Status.SKIP]
        if not shown:
            continue
        if cat == "project" and ctx.kinds:
            kind = next((r.summary for c, r in rows
                         if c.id == "project-kind"), "")
            title = f"Project ({ctx.target.name or ctx.target} — {kind})"
            shown = [(c, r) for c, r in shown if c.id != "project-kind"]
            if not shown:
                continue
        lines.append(title)
        for check, r in shown:
            mark = glyphs[r.status]
            if color:
                mark = f"{_COLORS[r.status]}{mark}{_RESET}"
            lines.append(f"  {mark} {r.summary}")
            if r.remedy and r.status in (Status.WARN, Status.FAIL):
                lines.append(f"      {glyphs['arrow']} {r.remedy}")
            if verbose and r.detail:
                for dl in r.detail.strip().splitlines():
                    lines.append(f"      {dl}")
        lines.append("")
    counts = report.counts()
    total = len(report.results)
    tail = f"({total} checks, {counts['skip']} skipped, " \
           f"{report.elapsed:.1f}s)"
    if counts["fail"] or counts["warn"]:
        bits = []
        if counts["fail"]:
            bits.append(f"{counts['fail']} failure"
                        + ("s" if counts["fail"] != 1 else ""))
        if counts["warn"]:
            bits.append(f"{counts['warn']} warning"
                        + ("s" if counts["warn"] != 1 else ""))
        dash = "—" if glyphs is _GLYPHS else "--"
        lines.append(f"{', '.join(bits)} {dash} fixes listed above. {tail}")
    else:
        lines.append(f"No issues found. {tail}")
    return "\n".join(lines)


def render_json(report: Report, ctx: Context, *,
                strict: bool = False) -> str:
    counts = report.counts()
    return json.dumps({
        "workpeg": {
            "version": ctx.workpeg_version,
            "editable": bool(ctx.workpeg_editable),
            "path": str(ctx.workpeg_file.parent),
        },
        "python": ".".join(map(str, ctx.py_version)),
        "platform": ctx.platform_str,
        # ok mirrors the exit code THIS run produces — a CI reading
        # {"ok": true} next to exit 1 would have two contradictory verdicts.
        "ok": report.exit_code(strict=strict) == 0,
        "strict": strict,
        "checks": [
            {"id": c.id, "category": c.category, "status": r.status.value,
             "summary": r.summary, "remedy": r.remedy, "detail": r.detail}
            for c, r in report.results
        ],
        "counts": counts,
    }, indent=2)


def _encodable(text: str, stream) -> str:
    """*text*, guaranteed printable on *stream*. Check summaries carry em
    dashes and paths carry arbitrary bytes; on a cp1252 pipe (Windows
    ``doctor > report.txt``) an unencodable character would raise inside
    print() — the cli handler would call that a doctor crash (exit 2) and
    the user would lose the very diagnosis they asked for. Degrade the
    characters, never the verdict."""
    enc = getattr(stream, "encoding", None) or "utf-8"
    try:
        text.encode(enc)
        return text
    except (UnicodeEncodeError, LookupError):
        return text.encode(enc, "replace").decode(enc, "replace")


# ── entry point (the cli handler calls this) ────────────────────────────


def run(args) -> int:
    target = Path(getattr(args, "path", ".") or ".")
    if not target.is_dir():
        print(f"ERROR: no such directory: {target}", file=sys.stderr)
        return 2
    ctx = build_context(target, offline=args.offline, timeout=args.timeout)
    report = run_doctor(ctx)
    if args.json:
        out = render_json(report, ctx, strict=args.strict)
    else:
        out = render_text(
            report, ctx,
            verbose=args.verbose,
            color=_use_color(sys.stdout),
            glyphs=_glyphs_for(sys.stdout),
        )
    print(_encodable(out, sys.stdout))
    return report.exit_code(strict=args.strict)
